// Language for the extension: the app's choice (sent with every /hello reply and kept in
// storage), otherwise the browser's language. Indonesian text in the code is the key;
// STRINGS_EN (strings.js, generated by scripts/l10n.py) holds the English.
let LANG = guessLang();

function guessLang() {
  const ui = (chrome.i18n && chrome.i18n.getUILanguage && chrome.i18n.getUILanguage()) || navigator.language || "en";
  return /^(id|ms)\b/i.test(ui) ? "id" : "en";
}

function t(key) {
  return LANG === "en" ? STRINGS_EN[key] || key : key;
}

async function loadLang() {
  const { appLang } = await chrome.storage.local.get("appLang");
  if (appLang === "id" || appLang === "en") LANG = appLang;
  return LANG;
}
